/* Whether this machine can make a complex operation, and what each machine does with a level-11 mission. Pure
 * decisions, with no game or loader state of their own, so the tests can ask every case.
 *
 * A complex operation is generated by every peer from the host's seed. A peer that cannot generate one must never be in
 * a mission that is one, and no peer may guess what the host decided: the host says so in one row of the shared table,
 * and a peer without the answer leaves instead of assuming one. */
#include <stdlib.h>
#include <windows.h>

#include "co.h"

static const char kNotThisBuild[] = "the game's code is not the build this mod was made for";

/* Why the complex part is off, or NULL when it is on. The order is the order a player can act on: HellForge first. */
const char* co_complex_refusal(const CoComplexNeeds* n)
{
    if (!n->capacity_call) return "this HellForge has no generation_capacity: update HellForge";
    if (!n->regions) return "this HellForge does not report the map generator's layout: update HellForge";
    if (n->live_load) return "the mod was loaded while the game ran: restart the game";
    if (!n->capacity_granted) return "HellForge refused the map generator's capacity (its log line says why)";
    if (!n->level_11) return "difficulty 11 is not installed (the Hell Forge mod is off or failed)";
    if (!n->moved) return "the map generator kept its own arrays";
    if (!n->early) return "the engine's pools and navigation grid were not enlarged as the game started";
    if (!n->render) return "the main world's culling pools were not enlarged as the game started";
    if (!n->stock_stubs) return "difficulty 11's larger-map steps are not the ones this mod was built for";
    if (!n->own_sites) return kNotThisBuild;
    if (!n->records) return "the entity records kept the game's 2048 places";
    if (n->ram_mb < CO_COMPLEX_RAM_MB) return "this PC has less than 16 GB of RAM";
    return NULL;
}

int co_complex_refused_build(const CoComplexNeeds* n) { return co_complex_refusal(n) == kNotThisBuild; }

/* What a machine does at a level-11 mission: `host_row` is the host's answer as this machine holds it. */
int co_complex_decision(int is_host, int own_on, int host_row, uint32_t mission_seed)
{
    int marked = co_seed_is_complex(mission_seed);
    if (is_host) return own_on && marked ? CO_MISSION_COMPLEX : CO_MISSION_NORMAL;
    if (host_row == CO_HOST_ROW_NONE) return CO_MISSION_LEAVE;
    if (host_row == CO_HOST_ROW_OFF) return CO_MISSION_NORMAL;
    if (!own_on) return CO_MISSION_LEAVE;
    return marked ? CO_MISSION_COMPLEX : CO_MISSION_NORMAL;
}

/* Whether a client stays in a session, asked when the host's row arrives or changes: a machine that cannot make a
 * complex operation goes before a mission can start. */
int co_complex_stays(int own_on, int host_row) { return own_on || host_row != CO_HOST_ROW_ON; }

int co_generation_decision(CoGeneration* g, uintptr_t level, uint32_t first_seed, int retry, uint32_t difficulty, int is_host, int own_on, int host_row)
{
    if (difficulty != CO_COMPLEX_LEVEL) { g->held = 0; return CO_MISSION_NORMAL; }
    if (retry && g->held && g->level == level) return g->decision; /* the session may have changed since; the generation has not */
    g->level = level; g->seed = first_seed; g->held = 1;
    g->decision = co_complex_decision(is_host, own_on, host_row, first_seed);
    return g->decision;
}

int co_complex_rolls(int is_host, int own_on, int host_row) { return is_host ? own_on != 0 : host_row == CO_HOST_ROW_ON; }

/* The others' chance beside each planet's guaranteed complex operation. A research build (no package is made from one)
 * takes HELLFORGE_CO_CHANCE, in 1/65536: 65536 makes every level-11 operation complex, 0 only each planet's
 * guaranteed one. Only the host's answer counts, so one machine's switch suffices. */
uint32_t co_complex_chance(void)
{
#ifdef CO_RESEARCH
    static int read;
    static uint32_t chance = CO_COMPLEX_CHANCE;
    char text[16];
    if (!read && (read = 1) && GetEnvironmentVariableA("HELLFORGE_CO_CHANCE", text, sizeof text) > 0)
    {
        const unsigned long v = strtoul(text, NULL, 10);
        chance = v > 65536ul ? 65536u : (uint32_t)v;
        co_log("complex operations: research switch: the roll's chance is %u in 65536 beside each planet's guaranteed one", chance);
    }
    return chance;
#else
    return CO_COMPLEX_CHANCE;
#endif
}

/* The seed a mission entry keeps: other levels' as the game made it; level 11's with the decision. Only a host whose
 * complex part is on rolls; a client marks its own board the same way for its war table when the host's row says on. */
uint32_t co_complex_entry_seed(uint32_t mission_seed, uint32_t difficulty, int complex)
{
    return difficulty != CO_COMPLEX_LEVEL ? mission_seed : co_seed_marked(mission_seed, complex);
}

int co_capability_read(const void* data, uint32_t bytes, uint64_t* peer)
{
    const CoCapability* c = (const CoCapability*)data;
    if (bytes != sizeof *c || c->protocol != CO_SHARE_PROTOCOL || c->peer == 0) return CO_PEER_UNKNOWN; /* not a message this build reads */
    *peer = c->peer;
    return c->on ? CO_PEER_ON : CO_PEER_OFF;
}

void co_reports_note(CoReports* r, uint64_t peer, int capability)
{
    uint32_t i = 0;
    if (peer == 0) return;
    while (i < r->count && r->rows[i].peer != peer) i++;
    if (i == CO_PEERS_MAX) return; /* no room: the machine stays unknown, which admits it to nothing */
    r->rows[i].peer = peer; r->rows[i].capability = (uint8_t)capability;
    if (i == r->count) r->count++;
}

int co_reports_get(const CoReports* r, uint64_t peer)
{
    for (uint32_t i = 0; i < r->count; i++) if (r->rows[i].peer == peer) return r->rows[i].capability;
    return CO_PEER_UNKNOWN;
}

int co_launch_clears(const CoReports* r, const uint64_t* present, uint32_t slots, uint64_t own, int own_on, int override_set)
{
    if (override_set) return 0;
    if (!own_on) return 1;
    for (uint32_t i = 0; i < slots; i++)
        if (present[i] != 0 && present[i] != own && co_reports_get(r, present[i]) != CO_PEER_ON) return 1;
    return 0;
}

int co_join_decision(int marked, int capability, uint64_t waited_ms)
{
    if (!marked || capability == CO_PEER_ON) return CO_JOIN_ADMIT;
    if (capability == CO_PEER_OFF) return CO_JOIN_DENY;
    return waited_ms < CO_JOIN_LIMIT_MS ? CO_JOIN_HOLD : CO_JOIN_DENY;
}
